9	export default async function InventoryPage() {
10	  const buyerProvince = await getBuyerProvince();
11	  const [{ units, dealers, dealerById }, meta, specs] = await Promise.all([
12	    loadScoredUnits(buyerProvince),
13	    loadMeta(),
14	    loadSpecs(),
15	  ]);
16	  const pressure = dealerPressureMap(units, dealers);
17	  const sm = specMap(specs);
18	  const rangeByUnitId: Record<string, number | null> = {};
19	  for (const u of units) {
20	    const s = sm.get(specKey(u.model, u.year, u.trim, u.drivetrain));
21	    rangeByUnitId[u.id] = s?.rangeKm ?? null;
22	  }
23	
24	  return (
25	    <div className="space-y-4">
26	      <div className="flex flex-wrap items-end justify-between gap-3">
27	        <div>
28	          <h1 className="text-2xl font-semibold tracking-tight">Inventory</h1>
29	          <p className="text-sm text-fg-muted">
30	            Filter, sort, and rank every tracked unit. Defaults to the Greater Golden Horseshoe.
31	          </p>
32	        </div>
33	        <UpdatedStamp
34	          rows={[
35	            { label: "Units updated", iso: meta.unitsUpdatedAt },
36	            { label: "Dealers updated", iso: meta.dealersUpdatedAt },
37	          ]}
38	        />
39	      </div>
40	      <InventoryTable
41	        units={units}
42	        dealerById={dealerById}
43	        dealerPressureByDealer={pressure}
44	        rangeByUnitId={rangeByUnitId}
45	      />
46	    </div>
47	  );
48	}
