3	import { useEffect, useMemo, useState } from "react";
4	import { usePathname, useRouter, useSearchParams } from "next/navigation";
5	import type { Dealer, ScoredUnit } from "@/lib/types";
6	import { MODEL_LABEL, GGH_CITIES, MODELS, SUPPORTED_YEARS, type Model } from "@/lib/constants";
7	import { fmtCad } from "@/lib/format";
8	import { effectivePreTaxValue } from "@/lib/scoring";
9	import { useFavorites } from "@/lib/useFavorites";
10	import { DealScoreBadge } from "./DealScoreBadge";
11	import { StatusChip } from "./StatusChip";
12	import { UnitDrawer } from "./UnitDrawer";
