14	// Days since lastSeen — used to chip rows that haven't been re-confirmed
15	// recently. Anything > 7 days is at risk of being sold or pulled.
16	function daysSince(iso: string): number {
17	  const t = new Date(iso).getTime();
18	  if (Number.isNaN(t)) return 0;
19	  return Math.max(0, Math.floor((Date.now() - t) / 86_400_000));
20	}
21	
22	// EVAP cap is the central 2026 buying-decision tool. We surface three
23	// states per unit: eligible (under cap, $5k applied to OTD), cliff
24	// (within $1,500 over the cap — small accessory cuts may unlock it), and
25	// over-cap (lost rebate, used for sorting and competitor benchmarking).
26	type EvapState = "eligible" | "cliff" | "over";
27	const CAP_CAD = 50000;
28	const CLIFF_BAND_CAD = 1500;
29	function evapStateFor(unit: ScoredUnit): EvapState {
30	  const hasEvap = unit.applicableIncentives.some((i) => i.id.startsWith("fed-evap"));
31	  if (hasEvap) return "eligible";
32	  // Post-OEM-cash effective contract value — matches scoring.ts cap check.
33	  const effective = effectivePreTaxValue(unit, unit.applicableIncentives);
34	  if (effective - CAP_CAD <= CLIFF_BAND_CAD) return "cliff";
35	  return "over";
36	}
37	
38	function EvapChip({ state, unit }: { state: EvapState; unit: ScoredUnit }) {
39	  if (state === "eligible") {
40	    return (
41	      <div
42	        className="text-xxs text-accent mt-0.5 font-normal"
43	        title="Pre-tax transaction value ≤ $50,000 → $5,000 federal EVAP rebate already applied to OTD"
44	      >
45	        EVAP −$5k
46	      </div>
47	    );
48	  }
49	  if (state === "cliff") {
50	    const effective = effectivePreTaxValue(unit, unit.applicableIncentives);
51	    const over = Math.round(effective - CAP_CAD);
52	    return (
53	      <div
54	        className="text-xxs text-warn mt-0.5 font-normal"
55	        title="Within $1,500 of EVAP cap. Trimming dealer add-ons (admin, wheel locks, prep) might unlock the $5k rebate."
56	      >
57	        Cliff +${over}
58	      </div>
59	    );
60	  }
61	  return null;
62	}
63	
64	type Props = {
65	  units: ScoredUnit[];
66	  dealerById: Map<string, Dealer>;
67	  dealerPressureByDealer: Record<string, number>;
68	  rangeByUnitId?: Record<string, number | null>;
69	};
70	
71	type SortKey = "deal" | "otd" | "discount" | "perKm" | "newest" | "oldest";
72	
73	const SORTS: { key: SortKey; label: string }[] = [
74	  { key: "deal", label: "Best deal score" },
75	  { key: "otd", label: "Lowest OTD" },
76	  { key: "discount", label: "Biggest discount vs MSRP" },
77	  { key: "perKm", label: "Lowest $/km of range" },
78	  { key: "newest", label: "Newest listing" },
79	  { key: "oldest", label: "Longest on lot" },
80	];
81	
82	// Aging signal: any prior-MY unit that's been sitting >90 days. Shoppers can
83	// usually negotiate hardest on these.
84	const CURRENT_MY = Math.max(...SUPPORTED_YEARS);
85	function isAgingOutgoing(year: number, daysOnLot?: number): boolean {
86	  return year < CURRENT_MY && (daysOnLot ?? 0) > 90;
87	}
88	
89	// E-GMP ICCU recall family. Ioniq 5 spans 2025; EV6 + Ioniq 6 stop at 2024.
90	// Source: data/market-intel.json (kept in sync there).
91	function iccuAffected(model: Model, year: number): boolean {
92	  if (model === "EV6" && year >= 2022 && year <= 2024) return true;
93	  if (model === "Ioniq5" && year >= 2022 && year <= 2025) return true;
94	  if (model === "Ioniq6" && year >= 2023 && year <= 2024) return true;
95	  return false;
96	}
97	
98	const VALID_SORTS: SortKey[] = ["deal", "otd", "discount", "perKm", "newest", "oldest"];
99	
100	const CSV_COLS = [
101	  "model", "year", "trim", "drivetrain", "exteriorColor", "interiorColor",
102	  "msrp", "asking", "otd", "daysOnLot", "lastSeen", "status",
103	  "dealerName", "dealerCity", "dealerProvince", "dealerPhone", "pressure",
104	  "listingUrl",
105	] as const;
106	
107	function csvEscape(val: string | number | undefined | null): string {
108	  if (val === undefined || val === null) return "";
109	  const s = String(val);
110	  if (s.includes(",") || s.includes('"') || s.includes("\n")) {
111	    return `"${s.replace(/"/g, '""')}"`;
112	  }
113	  return s;
114	}
115	
116	function modelBreakdown(units: ScoredUnit[]): string {
117	  const counts: Record<Model, number> = { EV6: 0, Ioniq5: 0, Ioniq6: 0, EV9: 0, Ioniq9: 0 };
118	  for (const u of units) counts[u.model] += 1;
119	  return (Object.keys(counts) as Model[])
120	    .filter((m) => counts[m] > 0)
121	    .map((m) => `${counts[m]} ${MODEL_LABEL[m]}`)
122	    .join(", ");
123	}
124	
125	function activeFilterChips(s: {
126	  model: Model | "all";
127	  year: number | "all";
128	  drivetrain: "RWD" | "AWD" | "all";
129	  region: "ggh" | "on" | "all";
130	  maxPrice: number | "";
131	  pressureOnly: boolean;
132	  evapOnly: boolean;
133	  query: string;
134	}): { key: string; label: string }[] {
135	  const out: { key: string; label: string }[] = [];
136	  if (s.model !== "all") out.push({ key: "model", label: MODEL_LABEL[s.model] });
137	  if (s.year !== "all") out.push({ key: "year", label: `MY ${s.year}` });
138	  if (s.drivetrain !== "all") out.push({ key: "drivetrain", label: s.drivetrain });
139	  if (s.region !== "ggh") out.push({ key: "region", label: s.region === "on" ? "All Ontario" : "All Canada" });
140	  if (s.maxPrice !== "") out.push({ key: "maxPrice", label: `≤ $${s.maxPrice.toLocaleString("en-CA")}` });
141	  if (s.pressureOnly) out.push({ key: "pressureOnly", label: "High pressure" });
142	  if (s.evapOnly) out.push({ key: "evapOnly", label: "EVAP eligible" });
143	  if (s.query.trim()) out.push({ key: "query", label: `"${s.query.trim()}"` });
144	  return out;
145	}
146	
147	function exportCsv(
148	  units: ScoredUnit[],
149	  dealerById: Map<string, Dealer>,
150	  pressureByDealer: Record<string, number>,
151	) {
152	  const header = CSV_COLS.join(",");
153	  const rows = units.map((u) => {
154	    const d = dealerById.get(u.dealerId);
155	    return [
156	      u.model, u.year, u.trim, u.drivetrain, u.exteriorColor, u.interiorColor,
157	      u.msrp, u.dealerAskingPrice, u.otdCad, u.daysOnLot ?? "", u.lastSeen, u.status,
158	      d?.name ?? "", d?.city ?? "", d?.province ?? "", d?.phone ?? "", pressureByDealer[u.dealerId] ?? 0,
159	      u.listingUrl ?? "",
160	    ].map(csvEscape).join(",");
161	  });
162	  const csv = [header, ...rows].join("\n");
163	  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
164	  const url = URL.createObjectURL(blob);
165	  const today = new Date().toISOString().slice(0, 10).replace(/-/g, "");
166	  const a = document.createElement("a");
167	  a.href = url;
168	  a.download = `ev-inventory-${today}.csv`;
169	  document.body.appendChild(a);
170	  a.click();
171	  document.body.removeChild(a);
172	  URL.revokeObjectURL(url);
173	}
