175	export function InventoryTable({ units, dealerById, dealerPressureByDealer, rangeByUnitId }: Props) {
176	  const rangeFor = (id: string): number | null => rangeByUnitId?.[id] ?? null;
177	  const perKmFor = (u: ScoredUnit): number | null => {
178	    const r = rangeFor(u.id);
179	    return r && r > 0 ? u.otdCad / r : null;
180	  };
181	  const router = useRouter();
182	  const pathname = usePathname();
183	  const searchParams = useSearchParams();
184	
185	  const initial = useMemo(() => {
186	    const m = searchParams.get("model");
187	    const y = searchParams.get("year");
188	    const dt = searchParams.get("dt");
189	    const rg = searchParams.get("region");
190	    const mp = searchParams.get("maxOtd");
191	    const po = searchParams.get("pressure");
192	    const ev = searchParams.get("evap");
193	    const so = searchParams.get("sort");
194	    const q = searchParams.get("q");
195	    const uid = searchParams.get("u");
196	    return {
197	      model: (m && (MODELS as readonly string[]).includes(m) ? (m as Model) : "all") as Model | "all",
198	      year: (y && SUPPORTED_YEARS.map(String).includes(y) ? Number(y) : "all") as number | "all",
199	      drivetrain: (dt === "RWD" || dt === "AWD" ? dt : "all") as "RWD" | "AWD" | "all",
200	      region: (rg === "on" || rg === "all" ? rg : "ggh") as "ggh" | "on" | "all",
201	      maxPrice: (mp && !Number.isNaN(Number(mp)) ? Number(mp) : "") as number | "",
202	      pressureOnly: po === "1",
203	      evapOnly: ev === "1",
204	      sort: ((so && VALID_SORTS.includes(so as SortKey)) ? (so as SortKey) : "deal") as SortKey,
205	      query: q ?? "",
206	      unitId: uid ?? null,
207	    };
208	    // eslint-disable-next-line react-hooks/exhaustive-deps
209	  }, []);
210	
211	  const [model, setModel] = useState<Model | "all">(initial.model);
212	  const [year, setYear] = useState<number | "all">(initial.year);
213	  const [drivetrain, setDrivetrain] = useState<"RWD" | "AWD" | "all">(initial.drivetrain);
214	  const [region, setRegion] = useState<"ggh" | "on" | "all">(initial.region);
215	  const [maxPrice, setMaxPrice] = useState<number | "">(initial.maxPrice);
216	  const [pressureOnly, setPressureOnly] = useState(initial.pressureOnly);
217	  const [evapOnly, setEvapOnly] = useState(initial.evapOnly);
218	  const [sort, setSort] = useState<SortKey>(initial.sort);
219	  const [query, setQuery] = useState<string>(initial.query);
220	  const [selectedId, setSelectedId] = useState<string | null>(initial.unitId);
221	  const [favoritesOnly, setFavoritesOnly] = useState(false);
222	  const { isFavorite, toggle: toggleFavorite, count: favoriteCount } = useFavorites();
223	
224	  useEffect(() => {
225	    const p = new URLSearchParams();
226	    if (model !== "all") p.set("model", model);
227	    if (year !== "all") p.set("year", String(year));
228	    if (drivetrain !== "all") p.set("dt", drivetrain);
229	    if (region !== "ggh") p.set("region", region);
230	    if (maxPrice !== "") p.set("maxOtd", String(maxPrice));
231	    if (pressureOnly) p.set("pressure", "1");
232	    if (evapOnly) p.set("evap", "1");
233	    if (sort !== "deal") p.set("sort", sort);
234	    if (query.trim()) p.set("q", query.trim());
235	    if (selectedId) p.set("u", selectedId);
236	    const qs = p.toString();
237	    router.replace(qs ? `${pathname}?${qs}` : pathname, { scroll: false });
238	  }, [model, year, drivetrain, region, maxPrice, pressureOnly, evapOnly, sort, query, selectedId, pathname, router]);
239	
240	  const filtered = useMemo(() => {
241	    const q = query.trim().toLowerCase();
242	    return units
243	      .filter((u) => {
244	        if (model !== "all" && u.model !== model) return false;
245	        if (year !== "all" && u.year !== year) return false;
246	        if (drivetrain !== "all" && u.drivetrain !== drivetrain) return false;
247	        const dealer = dealerById.get(u.dealerId);
248	        if (!dealer) return false;
249	        if (region === "ggh" && (dealer.province !== "ON" || !GGH_CITIES.includes(dealer.city))) return false;
250	        if (region === "on" && dealer.province !== "ON") return false;
251	        if (maxPrice && u.otdCad > Number(maxPrice)) return false;
252	        if (pressureOnly && (dealerPressureByDealer[dealer.id] ?? 0) < 50) return false;
253	        if (evapOnly && evapStateFor(u) !== "eligible") return false;
254	        if (favoritesOnly && !isFavorite(u.id)) return false;
255	        if (q) {
256	          const hay = `${u.trim} ${u.exteriorColor} ${u.interiorColor} ${u.vin ?? ""} ${u.stockNumber ?? ""} ${dealer.name} ${dealer.city}`.toLowerCase();
257	          if (!hay.includes(q)) return false;
258	        }
259	        return true;
260	      })
261	      .sort((a, b) => {
262	        if (sort === "deal") return b.dealScore - a.dealScore;
263	        if (sort === "otd") return a.otdCad - b.otdCad;
264	        if (sort === "discount") {
265	          const da = (a.msrp - a.dealerAskingPrice) / a.msrp;
266	          const db = (b.msrp - b.dealerAskingPrice) / b.msrp;
267	          return db - da;
268	        }
269	        if (sort === "perKm") {
270	          const pa = perKmFor(a);
271	          const pb = perKmFor(b);
272	          if (pa == null && pb == null) return 0;
273	          if (pa == null) return 1;
274	          if (pb == null) return -1;
275	          return pa - pb;
276	        }
277	        if (sort === "newest") return new Date(b.firstSeen).getTime() - new Date(a.firstSeen).getTime();
278	        return new Date(a.firstSeen).getTime() - new Date(b.firstSeen).getTime();
279	      });
280	  }, [units, dealerById, dealerPressureByDealer, model, year, drivetrain, region, maxPrice, pressureOnly, evapOnly, favoritesOnly, isFavorite, sort, query]);
281	
282	  const selected = useMemo(
283	    () => (selectedId ? units.find((u) => u.id === selectedId) ?? null : null),
284	    [selectedId, units],
285	  );
286	
287	  // Cheapest other listing of same model+year+trim — anchors the price ask in
288	  // the negotiation draft.
289	  const comparable = useMemo(() => {
290	    if (!selected) return undefined;
291	    return units
292	      .filter((u) =>
293	        u.id !== selected.id &&
294	        u.model === selected.model &&
295	        u.year === selected.year &&
296	        u.trim === selected.trim,
297	      )
298	      .sort((a, b) => a.otdCad - b.otdCad)[0];
299	  }, [selected, units]);
300	
301	  return (
302	    <div className="card overflow-hidden">
303	      <div className="p-3 border-b border-border flex flex-wrap items-center gap-2 text-xs">
304	        <input
305	          type="search"
306	          value={query}
307	          onChange={(e) => setQuery(e.target.value)}
308	          placeholder="Search trim, color, dealer, VIN…"
309	          className="px-2 py-1.5 w-56"
310	        />
311	        <select
312	          value={model}
313	          onChange={(e) => setModel(e.target.value as Model | "all")}
314	          className="px-2 py-1.5"
315	        >
316	          <option value="all">All models</option>
317	          {MODELS.map((m) => (
318	            <option key={m} value={m}>{MODEL_LABEL[m]}</option>
319	          ))}
320	        </select>
321	        <select
322	          value={year}
323	          onChange={(e) => setYear(e.target.value === "all" ? "all" : Number(e.target.value))}
324	          className="px-2 py-1.5"
325	        >
326	          <option value="all">All years</option>
327	          <option value={2024}>2024</option>
328	          <option value={2025}>2025</option>
329	          <option value={2026}>2026</option>
330	        </select>
331	        <select
332	          value={drivetrain}
333	          onChange={(e) => setDrivetrain(e.target.value as "RWD" | "AWD" | "all")}
334	          className="px-2 py-1.5"
335	        >
336	          <option value="all">RWD + AWD</option>
337	          <option value="RWD">RWD only</option>
338	          <option value="AWD">AWD only</option>
339	        </select>
340	        <select
341	          value={region}
342	          onChange={(e) => setRegion(e.target.value as "ggh" | "on" | "all")}
343	          className="px-2 py-1.5"
344	        >
345	          <option value="ggh">Greater Golden Horseshoe</option>
346	          <option value="on">All Ontario</option>
347	          <option value="all">All Canada</option>
348	        </select>
349	        <label className="flex items-center gap-1 text-fg-muted">
350	          Max OTD
351	          <input
352	            type="number"
353	            inputMode="numeric"
354	            value={maxPrice}
355	            onChange={(e) => setMaxPrice(e.target.value === "" ? "" : Number(e.target.value))}
356	            placeholder="65000"
357	            className="w-24 px-2 py-1.5 num"
358	          />
359	        </label>
360	        <label className="flex items-center gap-1.5 text-fg-muted cursor-pointer">
361	          <input
362	            type="checkbox"
363	            checked={pressureOnly}
364	            onChange={(e) => setPressureOnly(e.target.checked)}
365	          />
366	          High-pressure dealers only
367	        </label>
368	        <label
369	          className="flex items-center gap-1.5 text-fg-muted cursor-pointer"
370	          title="Pre-tax transaction value ≤ $50,000 — qualifies for $5,000 federal EVAP rebate"
371	        >
372	          <input
373	            type="checkbox"
374	            checked={evapOnly}
375	            onChange={(e) => setEvapOnly(e.target.checked)}
376	          />
377	          EVAP-eligible only
378	        </label>
379	        <label
380	          className="flex items-center gap-1.5 text-fg-muted cursor-pointer"
381	          title="Show only units you've starred"
382	        >
383	          <input
384	            type="checkbox"
385	            checked={favoritesOnly}
386	            onChange={(e) => setFavoritesOnly(e.target.checked)}
387	            disabled={favoriteCount === 0}
388	          />
389	          Favorites only ({favoriteCount})
390	        </label>
391	        <select
392	          value={sort}
393	          onChange={(e) => setSort(e.target.value as SortKey)}
394	          className="px-2 py-1.5 ml-auto"
395	        >
396	          {SORTS.map((s) => (
397	            <option key={s.key} value={s.key}>{`Sort: ${s.label}`}</option>
398	          ))}
399	        </select>
400	        <span className="text-fg-subtle" title={modelBreakdown(filtered)}>
401	          {filtered.length} units{filtered.length > 0 && ` · ${modelBreakdown(filtered)}`}
402	        </span>
403	        <button
404	          type="button"
405	          onClick={() => exportCsv(filtered, dealerById, dealerPressureByDealer)}
406	          className="px-2 py-1.5 border border-border rounded text-fg-muted hover:bg-bg-hover"
407	          disabled={filtered.length === 0}
408	        >
409	          Export CSV
410	        </button>
