139	  const cls = value > 0 ? "text-accent" : "text-warn";
140	  const sign = value > 0 ? "+" : "−";
141	  const abs = Math.abs(value);
142	  return <span className={cls}>{sign}{cad ? fmtCad(abs) : abs}</span>;
